#!/usr/bin/env node

const prog = require('caporal'),
{log} = require('./utils')

const { login, logout, registerRunner } = require('./actions')



prog
    .version('1.0.0')
    .command('login', 'start session')
    .action(login)

    .command('logout', 'drop currrent session')
    .action(logout)


    .command('runner', 'Create new runner for your app')
    .option('-t, --token', 'your project runner token', prog.STRING)
    .option('--desc <>', 'Some detail of your project', prog.STRING)
    .action(registerRunner);

prog.parse(process.argv);

